import numpy as np, pandas as pd
for f in ['spectrum_spot1.csv','spectrum_spot2.csv']:
    d=pd.read_csv(f); x=d.shift_cm1.values; y=d.intensity.values
    print(f, len(x), x.min(), x.max(), np.diff(x).mean().round(3), 'NaN:',np.isnan(y).sum(), 'min/max y', y.min(), y.max())
    # coarse table
    for lo in range(100,500,25):
        m=(x>=lo)&(x<lo+25)
        if m.any(): print(f'  {lo:4d}-{lo+25:4d}: max {y[m].max():9.1f} at {x[m][np.argmax(y[m])]:7.2f}  median {np.median(y[m]):8.1f}')
"

